import{_ as a,o as s,c as e,aN as n}from"./chunks/framework.D31DlcCL.js";const r="/img/math-statistics-intro.svg",c=JSON.parse('{"title":"小小统计员：小学数学初步统计入门","description":"统计是数学与生活的桥梁。本文将带小朋友们学习如何收集数据、整理数据，并画出漂亮的条形统计图。","frontmatter":{"title":"小小统计员：小学数学初步统计入门","date":"2026-02-09T10:00:00.000Z","categories":["数学"],"tags":["小学数学","统计","数据处理"],"description":"统计是数学与生活的桥梁。本文将带小朋友们学习如何收集数据、整理数据，并画出漂亮的条形统计图。","cover":"/img/math-statistics-intro.svg","top_img":"/img/math-statistics-intro.svg","toc_number":true},"headers":[],"relativePath":"posts/primary-math-statistics-intro.md","filePath":"posts/primary-math-statistics-intro.md","lastUpdated":null}'),l={name:"posts/primary-math-statistics-intro.md"};function o(i,t,p,m,h,d){return s(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="小小统计员-小学数学初步统计入门" tabindex="-1">小小统计员：小学数学初步统计入门 <a class="header-anchor" href="#小小统计员-小学数学初步统计入门" aria-label="Permalink to &quot;小小统计员：小学数学初步统计入门&quot;">​</a></h1><p>在生活中，我们经常要处理很多信息。比如：班里有多少人喜欢吃苹果？有多少人喜欢吃香蕉？这时候，我们就需要用到数学里的**“统计”**。</p><p>统计就像是一个“整理魔法”，能让乱糟糟的信息变得一目了然。</p><hr><h2 id="第一步-收集数据-正字计数法" tabindex="-1">第一步：收集数据（正字计数法） <a class="header-anchor" href="#第一步-收集数据-正字计数法" aria-label="Permalink to &quot;第一步：收集数据（正字计数法）&quot;">​</a></h2><p>当我们数东西的时候，可以用写“正”字的方法来记录。 为什么用“正”字呢？因为一个“正”字正好有 <strong>5 画</strong>，数起来特别方便！</p><p><img src="'+r+'" alt="初步统计图解"></p><p><strong>【小知识】</strong>：</p><ul><li>看到“正”，我们就知道是 5。</li><li>看到“正 丅”，就是 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mo>+</mo><mn>2</mn><mo>=</mo><mn>7</mn></mrow><annotation encoding="application/x-tex">5 + 2 = 7</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">5</span><span class="mbin">+</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">7</span></span></span></span>。</li></ul><hr><h2 id="第二步-整理数据-统计表" tabindex="-1">第二步：整理数据（统计表） <a class="header-anchor" href="#第二步-整理数据-统计表" aria-label="Permalink to &quot;第二步：整理数据（统计表）&quot;">​</a></h2><p>把数好的结果填进表格里，这就是<strong>统计表</strong>。</p><table tabindex="0"><thead><tr><th style="text-align:left;">水果名称</th><th style="text-align:left;">计数方法</th><th style="text-align:left;">数量 (个)</th></tr></thead><tbody><tr><td style="text-align:left;">苹果</td><td style="text-align:left;">正 正</td><td style="text-align:left;">10</td></tr><tr><td style="text-align:left;">香蕉</td><td style="text-align:left;">正 丅</td><td style="text-align:left;">7</td></tr><tr><td style="text-align:left;">梨子</td><td style="text-align:left;">正</td><td style="text-align:left;">5</td></tr></tbody></table><hr><h2 id="第三步-展示数据-条形统计图" tabindex="-1">第三步：展示数据（条形统计图） <a class="header-anchor" href="#第三步-展示数据-条形统计图" aria-label="Permalink to &quot;第三步：展示数据（条形统计图）&quot;">​</a></h2><p>如果我们想一眼看出谁多谁少，画成<strong>条形统计图</strong>最合适了。</p><ul><li>柱子越<strong>高</strong>，代表数量越<strong>多</strong>。</li><li>柱子越<strong>矮</strong>，代表数量越<strong>少</strong>。</li></ul><p>从上面的图表中，我们可以清晰地发现：<strong>喜欢苹果的人最多，喜欢梨子的人最少。</strong></p><hr><h2 id="四、-经典例题" tabindex="-1">四、 经典例题 <a class="header-anchor" href="#四、-经典例题" aria-label="Permalink to &quot;四、 经典例题&quot;">​</a></h2><p><strong>题目</strong>：下课了，操场上有 8 个小朋友在跳绳，5 个小朋友在踢球，12 个小朋友在跑步。请你用“正”字表示法记录下来，并说说哪种运动最受欢迎？</p><p><strong>解析</strong>：</p><ol><li><strong>跳绳</strong>：正 丅 (8)</li><li><strong>踢球</strong>：正 (5)</li><li><strong>跑步</strong>：正 正 丅 (12)</li></ol><p><strong>答案</strong>：跑步的小朋友最多，所以跑步最受欢迎。</p><hr><h2 id="五、-练一练" tabindex="-1">五、 练一练 <a class="header-anchor" href="#五、-练一练" aria-label="Permalink to &quot;五、 练一练&quot;">​</a></h2><ol><li><strong>分一分</strong>：数一数你书包里的书，语文书有几本？数学书有几本？绘本有几本？请你画一个简单的统计表。</li><li><strong>看图说话</strong>：如果统计图中，红色的柱子代表 8 人，蓝色的柱子比红色高出 2 格（每格代表 1 人），请问蓝色柱子代表多少人？</li></ol><hr><p><em>总结：统计不仅是数数，更是学会观察和分析。快去当一个小小的统计员吧！</em></p>',29)])])}const u=a(l,[["render",o]]);export{c as __pageData,u as default};
